package com.bank.jsoncmp.service;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;
import java.util.ArrayList;
import java.util.List;
import java.util.Iterator;
import java.util.Map;

// Logical JSON comparison: parse to trees, compare structurally. Ignores key
// order and whitespace, and offers numeric-aware equality for money fields.
@Service
public class JsonComparator {

    private static final Logger log = LoggerFactory.getLogger(JsonComparator.class);
    private final ObjectMapper mapper = new ObjectMapper();

    // Deep structural equality: order-independent for objects, order-sensitive
    // for arrays. Still distinguishes 50000 from 50000.0 (node types differ).
    public boolean equalsLogically(String json1, String json2) throws Exception {
        JsonNode a = mapper.readTree(json1);
        JsonNode b = mapper.readTree(json2);
        boolean result = a.equals(b);
        log.info("Logical equality (strict numeric) = {}", result);
        return result;
    }

    // Numeric-aware: compares numbers by value so 50000 equals 50000.00.
    public boolean equalsNumericAware(String json1, String json2) throws Exception {
        JsonNode a = mapper.readTree(json1);
        JsonNode b = mapper.readTree(json2);
        boolean result = a.equals(NUMERIC_COMPARATOR, b);
        log.info("Logical equality (numeric-aware) = {}", result);
        return result;
    }

    // Field-level diff: lists paths whose values differ between the two docs.
    public List<String> diff(String json1, String json2) throws Exception {
        JsonNode a = mapper.readTree(json1);
        JsonNode b = mapper.readTree(json2);
        List<String> changes = new ArrayList<>();
        walk("", a, b, changes);
        return changes;
    }

    private void walk(String path, JsonNode a, JsonNode b, List<String> changes) {
        if (a.isObject() && b.isObject()) {
            Iterator<Map.Entry<String, JsonNode>> fields = a.fields();
            while (fields.hasNext()) {
                Map.Entry<String, JsonNode> e = fields.next();
                String child = path.isEmpty() ? e.getKey() : path + "." + e.getKey();
                if (!b.has(e.getKey())) {
                    changes.add(child + ": removed");
                } else {
                    walk(child, e.getValue(), b.get(e.getKey()), changes);
                }
            }
            b.fieldNames().forEachRemaining(name -> {
                if (!a.has(name)) {
                    changes.add((path.isEmpty() ? name : path + "." + name) + ": added");
                }
            });
        } else if (!a.equals(NUMERIC_COMPARATOR, b)) {
            changes.add(path + ": " + a + " -> " + b);
        }
    }

    // Treats numeric nodes as equal when their decimal values match.
    private static final java.util.Comparator<JsonNode> NUMERIC_COMPARATOR = (x, y) -> {
        if (x.isNumber() && y.isNumber()) {
            return x.decimalValue().compareTo(y.decimalValue());
        }
        return x.equals(y) ? 0 : 1;
    };
}
