package com.bank.jsoncmp.controller;

import com.bank.jsoncmp.service.JsonComparator;
import org.springframework.web.bind.annotation.*;
import java.util.List;
import java.util.Map;

@RestController
@RequestMapping("/api/v1/compare")
public class CompareController {

    private final JsonComparator comparator;

    public CompareController(JsonComparator comparator) {
        this.comparator = comparator;
    }

    // Body carries two JSON documents under keys "a" and "b".
    @PostMapping("/equals")
    public Map<String, Object> equals(@RequestBody Map<String, String> body) throws Exception {
        return Map.of(
                "strict", comparator.equalsLogically(body.get("a"), body.get("b")),
                "numericAware", comparator.equalsNumericAware(body.get("a"), body.get("b")));
    }

    @PostMapping("/diff")
    public List<String> diff(@RequestBody Map<String, String> body) throws Exception {
        return comparator.diff(body.get("a"), body.get("b"));
    }
}
